package com.vodden.aoc

import kotlin.math.sqrt
import kotlin.requireNotNull

class Day08 {

    private val input by lazy { 
        val input = this::class.java.getResource("/input.txt")
            ?.readText()?.lines()

        requireNotNull(input) {"Failed to read input file"}
        input
    }

    private val junctionBoxes by lazy {
        input.map {  it.split(",").map { it.toLong() } }
    }


    fun part1(connections: Int = 1000) : Int {
        val sortedPairs = junctionBoxes.flatMap { lhs -> junctionBoxes.map { rhs -> Pair(lhs, rhs) } }
            .filter { (a, b) -> a != b }
            .sortedBy { (a, b) -> 
                val dx = a[0] - b[0]
                val dy = a[1] - b[1]
                val dz = a[2] - b[2]
                (dx * dx + dy * dy + dz * dz)
            }

        val circuits = hashMapOf<List<Long>, Set<List<Long>>>(*junctionBoxes.map { p -> p to setOf(p) }.toTypedArray())
        
        sortedPairs.take(connections).forEach { (a, b) ->
            val setA = circuits[a]!!
            val setB = circuits[b]!!
            if (setA != setB) {
                val merged = setA + setB
                merged.forEach { p -> circuits[p] = merged }
            }
        }

        

        return 0
    }
    
    fun part2() : Long {
        return 0L
    }
}

fun main() {
    println(Day08().part1())
    println(Day08().part2())
}